SELECT AVG(MAX(labevents.value)) OVER (PARTITION BY icustays.stay_id) AS avg_max_map FROM patients JOIN admissions ON patients.subject_id = admissions.subject_id JOIN icustays ON admissions.stay_id = icustays.stay_id JOIN labevents ON (icustays.stay_id = labevents.subject_id AND labevents.charttime BETWEEN icustays.intime AND icustays.outtime) WHERE patients.gender = 'M' AND patients.anchor_age = 53 AND EXTRACT(YEAR FROM icustays.intime) BETWEEN 2015 AND 2016 AND EXTRACT(YEAR FROM icustays.outtime) BETWEEN 2015 AND 2016 AND d_labitems.itemid = 8716780 AND (labevents.value::FLOAT > 100 OR (labevents.value::FLOAT <= 100 AND labevents.valueuom = 'mmHg'));